            input.removeAttribute('aria-invalid');
            errorElement.hidden = true;
            if (describedBy.includes(errorId)) {
                const newDescribedBy = describedBy.replace(errorId, '').replace(/\s+/g, ' ').trim();
                if (newDescribedBy) {
                    input.setAttribute('aria-describedby', newDescribedBy);
                } else {
                    input.removeAttribute('aria-describedby');
                }
            }
        }
    };

    // Add input event listeners to clear errors on user input dynamically
    fields.forEach(f => {
        const input = document.getElementById(f.id);
        const errorId = `${f.id}-error`;
        input.addEventListener('input', () => {
            if (input.hasAttribute('aria-invalid')) {
                // If they are typing and fix the error, clear the error message
                if (f.checkValid(input.value, input)) {
                    setError(input, errorId, false);
                }
            }
        });
    });

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isValid = true;
        let firstInvalidField = null;

        fields.forEach(f => {
